"""Audit 121: text_length_32001. Category: value-boundaries."""
from client import *

body = {'data': {'sashiny': 1, 'program': 'program.sas', 'title': 'Audit', 'inputs': {'x': {'type': 'text', 'label': 'X', 'max_length': 32000}}, 'outputs': {'report': {'type': 'log'}}}, 'values': {'x': ''}}
failures = []
for language in ('python', 'r'):
    try:
        got = value(language, 'values', body)
        assert codes(got) == [('V006','x')], got
    except AssertionError as exc:
        failures.append((language, str(exc)))
assert not failures, failures
